/**
 * Links to a page's sections, the current marked (`design/components/table-of-contents.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table-of-contents.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  agentMember,
  agentPress,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  jumpToSection,
  watchEffect,
  watchSections,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/table-of-contents.module.css'

export interface TableOfContentsItem {
  id: string
  label: string
  level?: 1 | 2
}

export interface TableOfContentsProps {
  /**
   * One link per section, in the page's order.
   */
  items: TableOfContentsItem[]
  /**
   * The landmark's name, drawn above the list ("On this page").
   */
  label: string
  /**
   * Called with the current section's id, or `null`, each time it changes.
   */
  onCurrentChange?: (id: string | null) => void
}

/** Links to a page's sections, the current marked. */
export default function TableOfContents(given: TableOfContentsProps): JSX.Element {
  const props = claimSlot(given)
  const uid = createUniqueId()
  const current = createCell(null as string | null)
  const nav = elementRef<HTMLElement>()
  const labelId = createDerived(() => `${uid}-label`)
  const groups = createDerived(() =>
    props.items.reduce(
      (groups, item, at) => {
        const parent = groups[groups.length - 1]
        if (item.level === 2 && parent !== undefined) parent.children.push({ item, at })
        else groups.push({ item, at, children: [] })
        return groups
      },
      [] as {
        item: TableOfContentsItem
        at: number
        children: { item: TableOfContentsItem; at: number }[]
      }[],
    ),
  )
  const currentAt = createDerived(() => props.items.findIndex((item) => item.id === current.value))
  let release1: (() => void) | undefined
  const effect1 = () => {
    release1?.()
    const ran = watchSections(
      nav.value,
      props.items.map((item) => item.id),
      (id) => {
        if (id === current.value) return
        current.value = id
        props.onCurrentChange?.(id)
      },
    )
    release1 = () => {
      ran()
    }
  }
  watchEffect(
    createMemo(() => props.items.map((item) => item.id).join(' ')),
    effect1,
    true,
  )
  onCleanup(() => release1?.())
  let release2: (() => void) | undefined
  const effect2 = () => {
    release2?.()
    const ran = agentMember({
      member: 'TableOfContents',
      element: () => nav.value,
      state: () => ({
        current: current.value,
        items: props.items
          .filter((item, at) => props.items.findIndex((other) => other.id === item.id) === at)
          .map((item) => ({ id: item.id, label: item.label })),
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) =>
            agentPress(
              nav.value?.querySelectorAll('a')[props.items.findIndex((item) => item.id === value)],
            ),
        },
      },
    })
    release2 = () => {
      ran()
    }
  }
  onMount(effect2)
  onCleanup(() => release2?.())
  return (
    <nav
      class={styles.nav}
      aria-labelledby={labelId.value}
      data-member="table-of-contents"
      ref={nav.attach}
    >
      {/* label */}
      <p class={styles.label} id={labelId.value}>
        {props.label}
      </p>
      {/* list */}
      <ul class={styles.list}>
        <Each of={groups.value} by={(group) => `${group.at}:${group.item.id}`} renew>
          {(group) => (
            <li class={styles.item}>
              {/* link */}
              <a
                class={styles.link}
                href={`#${group.item.id}`}
                aria-current={group.at === currentAt.value ? 'location' : undefined}
                onclick={($event: MouseEvent) => jumpToSection(nav.value, group.item.id, $event)}
              >
                {group.item.label}
              </a>
              {group.children.length > 0 ? (
                <ul class={styles.sublist}>
                  <Each of={group.children} by={(child) => `${child.at}:${child.item.id}`} renew>
                    {(child) => (
                      <li class={styles.item}>
                        {/* link */}
                        <a
                          class={styles.link}
                          href={`#${child.item.id}`}
                          aria-current={child.at === currentAt.value ? 'location' : undefined}
                          onclick={($event: MouseEvent) =>
                            jumpToSection(nav.value, child.item.id, $event)
                          }
                        >
                          {child.item.label}
                        </a>
                      </li>
                    )}
                  </Each>
                </ul>
              ) : null}
            </li>
          )}
        </Each>
      </ul>
    </nav>
  )
}
